ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2
| (ImageFileName=/\\rclone\.exe$/i OR CommandLine=/rclone/i)
| CommandLine=/\s(copy|sync|copyto|moveto)\s/i
| CommandLine=/(mega:|mega\.nz|mega\.co\.nz|pcloud|backblazeb2|\sb2:|wasabi|dropbox|gdrive:|--config|--transfers|--multi-thread-streams)/i
| case {
    ImageFileName=/\\(ProgramData|Users\\Public|Temp|AppData\\Local\\Temp|Intel|PerfLogs)\\[^\\]+\.exe$/i | masquerade := "1";
    *                                                                                                       | masquerade := "0";
  }
| groupBy([aid, ComputerName, UserName], function={ count(as=events) | max(masquerade, as=masq) | collect([ImageFileName, CommandLine, ParentBaseFileName, SHA256HashData]) })
| sort(_count, order=desc)
